	value := args[2]
	var expireAt int64 // 0 = no expiry

	// Parse optional arguments starting at index 3
	i := 3
	hasEX := false
	hasPX := false
	for i < len(args) {
		opt := strings.ToUpper(args[i])
		switch opt {
		case "EX":
			if hasPX || hasEX {
				writeError(w, "ERR syntax error")
				return
			}
			i++
			if i >= len(args) {
				writeError(w, "ERR syntax error")
				return
			}
			secs, err := strconv.ParseInt(args[i], 10, 64)
			if err != nil {
				writeError(w, "ERR value is not an integer or out of range")
				return
			}
			if secs <= 0 {
				writeError(w, fmt.Sprintf("ERR invalid expire time in '%s' command", args[0]))
				return
			}
			hasEX = true
			expireAt = time.Now().UnixMilli() + secs*1000
			i++
		case "PX":
			if hasEX || hasPX {
				writeError(w, "ERR syntax error")
				return
			}
			i++
			if i >= len(args) {
				writeError(w, "ERR syntax error")
				return
			}
			ms, err := strconv.ParseInt(args[i], 10, 64)
			if err != nil {
				writeError(w, "ERR value is not an integer or out of range")
				return
			}
			if ms <= 0 {
				writeError(w, fmt.Sprintf("ERR invalid expire time in '%s' command", args[0]))
				return
			}
			hasPX = true
			expireAt = time.Now().UnixMilli() + ms
			i++
		default:
			writeError(w, "ERR syntax error")
			return
		}
