// ─── Main ────────────────────────────────────────────────────────────────────

func main() {
	port := flag.Int("port", 6380, "TCP port to listen on")
	flag.Parse()

	db := newStore()

	addr := fmt.Sprintf("127.0.0.1:%d", *port)
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatalf("Failed to listen on %s: %v", addr, err)
	}
